// -- widget.h -- (Client-facing header)
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor declared but not defined in-line

    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

    // Copy operations could be supported by implementing them manually
    Widget(const Widget& other);
    Widget& operator=(const Widget& other);

private:
    // Pimpl: Pointer to implementation
    // Forward-declared, not defined here
    struct Impl;
    std::unique_ptr<Impl> pImpl;
};


// -- widget.cpp -- (Implementation file)
#include "widget.h"
#include <string>

// Full definition of the implementation is here
struct Widget::Impl {
    std::string name;
    int value;
};

// Destructor is now defined where Impl is a complete type
Widget::~Widget() = default;

// Constructor can now access members of the complete type Impl
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}

// Move operations are also defined here
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;

// Copy operations require a deep copy of the implementation
Widget::Widget(const Widget& other) 
    : pImpl(std::make_unique<Impl>(*other.pImpl)) {}
Widget& Widget::operator=(const Widget& other) {
    if (this != &other) {
        *pImpl = *other.pImpl;
    }
    return *this;
}
